      "https://brandvanegmond.com/wp-content/uploads/2023/05/BvE_Primavera_element-PRI30BDP_bronze-dark-patina_compo-round-x3_wb-scaled.jpg",
      "https://brandvanegmond.com/wp-content/uploads/2023/05/Brandvanegmond_Primavera_Element_PRI30BDP-01.jpg",
      "https://brandvanegmond.com/wp-content/uploads/2023/05/BvE_Primavera_element_PRI30WM_white-matt_bb_2-scaled.jpg",
