    "colorOptions": [
      "nickel",
      "gold"
    ],
    "longDescription": [
      "VICTORIA Conical Chandelier brings the sparkle of high-clarity crystal into a more vertical, theatrical silhouette. Cascades of crystal descend from a hand-shaped metal structure, catching the light in layers and creating a refined waterfall effect.",
      "Its conical shape gives the chandelier a natural sense of height and presence, working beautifully in stairwells, entrance halls, double-height spaces, landings and rooms where the eye is invited to travel upward. The design feels elegant and expressive, with crystal strands emphasising its vertical rhythm.",
      "Crafted by hand in our atelier, VICTORIA can be adapted in size, finish and proportions to suit the architecture and atmosphere of the interior.",
      "For a more enduring expression of this design language, discover the ARTHUR Conical Chandelier, where hand-forged metal stripes create a refined interplay of glimmers and reflections.",
      "— William Brand, creator and sculptor"
    ],
