      "VICTORIA Wall Lamp brings the sparkle of the collection to the vertical surfaces of the interior. High-refractive crystal glass strands fall from a hand-shaped metal structure, catching the light with a soft shimmer and creating an elegant accent on the wall.",
      "Offered in two sizes, it works beautifully beside mirrors, in corridors, bedrooms, dining rooms, entrance halls and hospitality interiors, either as a single luminous detail or in pairs for a more formal setting. The wall lamp adds depth and reflection, making it ideal for layering light within an interior.",
      "Crafted by hand in our atelier, VICTORIA can be adapted in size, finish and proportions to suit the architecture and atmosphere of the interior.",
