      "Semi-precious stones, rare minerals, and delicate objects of desire are carefully selected in their untouched state and woven into a sculptural embrace of hand-forged metal.",
      "In addition to our curated collection of gems — amethyst, pyrite, malachite, rock crystal, labradorite, calcite and fine porcelain Nymphenburg rose — the ORPHEUS Wall Lamp may be personalised with a cherished mineral or stone from your own collection.",
