      "https://brandvanegmond.com/wp-content/uploads/2025/03/BvE_TakaraCandles_TAKCHL160BDP_hanging-lamp-long_patina_white-scaled.jpg",
      "https://brandvanegmond.com/wp-content/uploads/2025/03/BvE_TakaraCandles_TAKCHL140N_hanging-lamp-long_nickel_white-scaled.jpg",
      "https://brandvanegmond.com/wp-content/uploads/2025/03/BvE_TakaraCandles_TAKCHL140N_hanging-lamp-long_nickel_rendering-scaled.jpg",
