    "dimensions": "Length: 140 cm · Width: 40 cm · Height: 30 cm",
    "colorOptions": [
      "nickel",
      "brown"
    ],
    "longDescription": [
      "TAKARA CANDLES translates the force and irregular beauty of nature into a sculptural lighting object, formed by hand and guided by material. Inspired by windswept driftwood, the hand-sculpted metal structure follows the organic rhythm of branches shaped by wind and water.",
      "Mouth-blown satin glass candles, set on hand-shaped branches, bring a gentle, atmospheric glow. Discreet integrated downlights are set beneath, providing focused illumination on the surface below. These can be switched and dimmed separately, allowing the object to move between functional clarity and a more subdued presence.",
      "Aligned above a dining table, kitchen island, or architectural axis, TAKARA CANDLES introduces texture, warmth, and a grounded, linear presence that connects the space.",
      "Crafted by hand in our atelier, each object is shaped individually and can be adapted in size, finish, and arrangement, forming the basis for bespoke variations and further developments within the collection.",
      "— William Brand, creator and sculptor"
    ],
