    "longDescription": [
      "SOIRÉE was envisioned by William Brand as a light for gathering: generous, refined, and quietly festive. A long, slender horizontal plane is suspended in space, carrying mouth-blown satin glass candles that rise in subtle variation, casting a warm, diffused glow.  Below, discreet integrated downlights project light onto the surface beneath. The two light sources operate independently, allowing the piece to shift from functional clarity to a more intimate, atmospheric setting.",
      "The composition is anchored on a tray finished in either Gold Colour or Nickel, with other finishes available on request. Each object can be adapted in size, finish, and configuration, making SOIRÉE not only a finished design but also a starting point for bespoke variations and related lighting objects.",
      "Suspended above a dining table, kitchen island, or long console, SOIRÉE forms a quiet horizon of light — an architectural line that defines the space, and reflects softly across surrounding materials.",
      "— William Brand, creator and sculptor"
    ],
