    "colorOptions": [
      "nickel",
      "gold"
    ],
    "longDescription": [
      "VICTORIA Round Chandelier captures the first impression of light: the sparkle that reaches the eye before the chandelier fully reveals itself. Cascades of jewel-like crystal glass fall from a layered metal structure, creating a refined waterfall of light. Each crystal strand moves gently and catches the glow from a different angle, seducing the light.",
      "The crystal strands bring rhythm and a soft, shimmering brilliance, while the metal structure gives the design its graceful and precise balance.",
      "This round chandelier gathers this brilliance at the centre of the room. Its harmonious silhouette makes it especially suited above dining tables, in salons, entrance halls, lobbies or central seating areas and refined hospitality interiors.",
      "For a more enduring expression of this design language, discover the ARTHUR Round Chandelier, where hand-forged metal stripes create a refined interplay of glimmers and reflections.",
      "— William Brand, creator and sculptor"
    ],
