      "https://brandvanegmond.com/wp-content/uploads/2025/03/BvE_BubblesTwilight_BUBTC100BDP_chandelier-round_bronze-dark-patina_white-scaled.jpg",
      "https://brandvanegmond.com/wp-content/uploads/2026/05/BvE_Fashion-Lighting-Group_Showroom_Bubbles-Twilight_BUBTC100BDP-3-scaled.jpg",
