    "dimensions": "Diameter: 80 cm · Height: 55 cm",
    "colorOptions": [
      "gold",
      "brown",
      "nickel"
    ],
    "longDescription": [
      "BUBBLES TWILIGHT brings a deeper, more atmospheric expression to the BUBBLES family. Hand-forged metal arms move freely through space, looping and intertwining to form an open network of lines that carry mouth-blown glass spheres in smoky grey and clear glass.",
      "The smoky grey spheres introduce depth and softness, while clear elements sharpen and articulate the whole. These can be exchanged or combined with iridescent and clear glass elements from other BUBBLES collections, allowing the object to become more subtle or more expressive depending on the interior.",
      "Suspended above a central table, in a study, or within an open double-height living space, BUBBLES TWILIGHT brings sculptural presence with depth and movement, animating the space without overwhelming it.",
      "Crafted by hand in our atelier, each object can be adapted in scale, finish, and arrangement, offering a high degree of freedom for both residential and hospitality projects.",
      "— William Brand, creator and sculptor"
    ],
