    "longDescription": [
      "SALSA draws the classic chandelier with a new line. Hand-forged metal arms sweep, arc, cross and return to form a luminous circular crown suspended in space. The lines carry tension and lift, their graphic silhouette unfolding with the controlled rhythm of a choreographed movement.",
      "From this structure rise slender stems crowned with mouth-blown glass candles. Their softly frosted glow recalls the lineage of candlelit chandeliers, while the open metal framework gives the form a sharper, more contemporary expression.",
      "Crafted to order in our atelier, the hand-sculpted structure allows variations in size, finish and arrangement to respond precisely to its architectural setting.",
      "SALSA reveals different qualities as the architecture shifts. Suspended above a dining table, shaping a seating area, or marking the centre of a lobby or entrance hall, its sweeping arms echo the tradition of the grand chandelier while translating it into a lighter, more fluid language that feels at ease in both classical architecture and contemporary interiors.",
      "— William Brand, creator and sculptor"
    ],
